import React, { useState, useEffect } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg';

const GuiYeuCauBaoTri = () => {
    const now = new Date();
    const [selectedDate, setSelectedDate] = useState(now.getDate());
    const [selectedMonth, setSelectedMonth] = useState(now.getMonth() + 1);
    const [selectedYear, setSelectedYear] = useState(now.getFullYear());

    const [userRoom, setUserRoom] = useState('');
    const [title, setTitle] = useState('');
    const [description, setDescription] = useState('');
    const [dailyRequests, setDailyRequests] = useState([]);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        const profile = JSON.parse(localStorage.getItem('userProfile') || '{}');
        setUserRoom(profile.room_id || profile.room || '102');
        fetchData();
    }, [selectedDate, selectedMonth, selectedYear]);

    // SAU NÀY THAY THẾ: Gọi API lấy danh sách yêu cầu của phòng này
    const fetchData = () => {
        setLoading(true);
        const allData = JSON.parse(localStorage.getItem('maintenance_db') || '[]');
        const filtered = allData.filter(item => 
            item.day === selectedDate && item.month === selectedMonth && item.year === selectedYear
        );
        setTimeout(() => { // Giả lập độ trễ mạng
            setDailyRequests(filtered);
            setLoading(false);
        }, 300);
    };

    // SAU NÀY THAY THẾ: Gọi API POST để gửi dữ liệu lên Server
    const handleSendRequest = async () => {
        if (!title.trim() || !description.trim()) return alert("Vui lòng điền đủ thông tin!");

        const newRequest = {
            id: Date.now(), // Backend sẽ tự tạo ID trong tương lai
            room: userRoom,
            title: title,
            issue: description,
            status: 'pending',
            day: selectedDate,
            month: selectedMonth,
            year: selectedYear,
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        };

        try {
            const allData = JSON.parse(localStorage.getItem('maintenance_db') || '[]');
            localStorage.setItem('maintenance_db', JSON.stringify([newRequest, ...allData]));

            setTitle(''); setDescription('');
            fetchData();
            alert("Gửi yêu cầu thành công!");
        } catch (error) {
            alert("Lỗi khi gửi yêu cầu!");
        }
    };

    return (
        <div style={containerStyle}>
            <div style={headerStyle}>
                <h2 style={{ color: '#fff', margin: 0, fontSize: '20px' }}>🛠 YÊU CẦU BẢO TRÌ</h2>
                <div style={{ display: 'flex', gap: '10px' }}>
                    <select value={selectedDate} onChange={(e) => setSelectedDate(Number(e.target.value))} style={selectStyle}>
                        {Array.from({length:31},(_,i)=><option key={i+1} value={i+1}>Ngày {i+1}</option>)}
                    </select>
                    <select value={selectedMonth} onChange={(e) => setSelectedMonth(Number(e.target.value))} style={selectStyle}>
                        {[...Array(12)].map((_, i) => <option key={i+1} value={i+1}>Tháng {i+1}</option>)}
                    </select>
                </div>
            </div>

            <div style={contentWrapperStyle}>
                <div style={mainLayout}>
                    {/* KHỐI TRẮNG RÕ (Học từ XemHoaDon) */}
                    <div style={whiteFormCard}>
                        <div style={roomDisplay}>
                            <span style={{ fontSize: '13px', color: '#8b5e5e', fontWeight: 'bold' }}>SỐ PHÒNG</span>
                            <div style={{ fontSize: '32px', fontWeight: '900', color: '#333' }}>{userRoom}</div>
                        </div>

                        <div style={inputGroup}>
                            <label style={labelStyle}>Tiêu đề sự cố:</label>
                            <input style={inputStyle} value={title} onChange={(e) => setTitle(e.target.value)} placeholder="VD: Hỏng vòi nước..." />
                        </div>
                        <div style={inputGroup}>
                            <label style={labelStyle}>Mô tả chi tiết:</label>
                            <textarea style={textareaStyle} value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Mô tả cụ thể..." />
                        </div>
                        <button onClick={handleSendRequest} style={btnPayStyle}>GỬI YÊU CẦU</button>
                    </div>

                    {/* KHỐI DANH SÁCH (Học từ XemHoaDon) */}
                    <div style={whiteListCard}>
                        <h3 style={{ color: '#8b5e5e', fontSize: '16px', textAlign: 'center', marginBottom: '15px' }}>LỊCH SỬ GỬI</h3>
                        {loading ? <div style={statusMsg}>Đang tải...</div> : (
                            <div style={{ overflowY: 'auto', flex: 1 }} className="custom-scrollbar">
                                {dailyRequests.length > 0 ? dailyRequests.map(req => (
                                    <div key={req.id} style={itemBox}>
                                        <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                                            <strong style={{fontSize: '14px'}}>P.{req.room}: {req.title}</strong>
                                            <span style={badgeStyle(req.status)}>{req.status === 'pending' ? 'Chờ' : 'Xong'}</span>
                                        </div>
                                        <div style={{ fontSize: '11px', color: '#999', marginTop: '5px' }}>Gửi lúc: {req.time}</div>
                                    </div>
                                )) : <div style={statusMsg}>Trống</div>}
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

// Styles đồng bộ XemHoaDon
const containerStyle = { flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover', backgroundPosition: 'center', height: 'calc(100vh - 120px)', overflow: 'hidden' };
const headerStyle = { padding: '20px 30px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', background: 'rgba(0,0,0,0.3)', backdropFilter: 'blur(10px)' };
const selectStyle = { padding: '8px 12px', borderRadius: '10px', border: 'none', fontWeight: 'bold' };
const contentWrapperStyle = { flex: 1, display: 'flex', padding: '25px', overflow: 'hidden' };
const mainLayout = { display: 'flex', gap: '20px', width: '100%' };
const whiteFormCard = { width: '380px', backgroundColor: '#fff', borderRadius: '30px', padding: '30px', boxShadow: '0 15px 35px rgba(0,0,0,0.2)' };
const whiteListCard = { flex: 1, backgroundColor: 'rgba(255, 255, 255, 0.9)', borderRadius: '30px', padding: '30px', display: 'flex', flexDirection: 'column' };
const roomDisplay = { textAlign: 'center', padding: '12px', background: '#fdf3f3', borderRadius: '20px', marginBottom: '20px', border: '2px dashed #8b5e5e' };
const inputGroup = { marginBottom: '15px' };
const labelStyle = { display: 'block', fontWeight: 'bold', marginBottom: '8px', color: '#666', fontSize: '13px' };
const inputStyle = { width: '100%', padding: '12px', borderRadius: '12px', border: '1px solid #ddd', outline: 'none' };
const textareaStyle = { ...inputStyle, height: '100px', resize: 'none' };
const btnPayStyle = { width: '100%', padding: '16px', borderRadius: '15px', border: 'none', backgroundColor: '#8b5e5e', color: '#fff', fontWeight: 'bold', cursor: 'pointer' };
const itemBox = { padding: '12px', background: '#f9f9f9', borderRadius: '15px', marginBottom: '10px', borderLeft: '4px solid #8b5e5e' };
const badgeStyle = (s) => ({ fontSize: '10px', padding: '3px 8px', borderRadius: '8px', background: s==='pending'?'#ffebeb':'#ebffef', color: s==='pending'?'#e03131':'#2f9e44', fontWeight: 'bold' });
const statusMsg = { textAlign: 'center', color: '#999', marginTop: '50px' };

export default GuiYeuCauBaoTri;
